using Logic.Contracts;

namespace Logic.CollisionResolution;

/// <summary>
/// A UUID-based collision resolution strategy that uses GUIDs to ensure uniqueness in distributed systems.
/// This strategy is suitable for high-throughput distributed deployments where collision probability is high.
/// </summary>
public class UuidCollisionResolutionStrategy : ICollisionResolutionStrategy
{
    /// <summary>
    /// Generates a unique short URL using UUID-based collision resolution.
    /// </summary>
    /// <param name="baseShortUrl">The base short URL generated by the primary shortener.</param>
    /// <param name="attempt">The current attempt number (0-based).</param>
    /// <param name="longUrl">The original long URL being shortened.</param>
    /// <returns>A unique short URL using UUID-based collision resolution.</returns>
    public string GenerateUniqueShortUrl(string baseShortUrl, int attempt, string longUrl)
    {
        ArgumentException.ThrowIfNullOrEmpty(baseShortUrl);
        ArgumentException.ThrowIfNullOrEmpty(longUrl);

        if (attempt < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(attempt), "Attempt number must be non-negative.");
        }

        // For attempt 0, return the base short URL (deterministic)
        if (attempt == 0)
        {
            return baseShortUrl;
        }

        // For retry attempts, use a UUID-based approach
        // Generate a short UUID (first 8 characters) and append it to the base short URL
        var uuid = Guid.NewGuid().ToString("N")[..8]; // Remove hyphens and take first 8 chars
        return $"{baseShortUrl}_{uuid}";
    }
}
